#include <vector>
#include <algorithm>

using namespace std;


class Solution {
public:
    int countPairs(TreeNode* root, int distance) {
        int count = 0;
        dfs(root, distance, count);
        return count;
    }

    vector<int> dfs(TreeNode* node, int distance, int& count) {
        if (!node) return {};
        if (!node->left && !node->right) return {1};

        vector<int> left = dfs(node->left, distance, count);
        vector<int> right = dfs(node->right, distance, count);

        for (int l : left)
            for (int r : right)
                if (l + r <= distance)
                    count++;

        vector<int> res;
        for (int l : left) if (l + 1 < distance) res.push_back(l + 1);
        for (int r : right) if (r + 1 < distance) res.push_back(r + 1);

        return res;
    }
};
